-- Resources content for NPR and weather moving under one Sources tab in Log
-- (CLAUDE.md, "Resources stay in step with the code"). The guide that
-- described the two old tabs is rewritten and attached to the new
-- log.sources screen, and one release note is added. Content only — no schema.

select private.rc_release_guide(
  p_slug => 'log-npr-and-weather',
  p_tool_key => 'log',
  p_title => 'Sources: NPR and weather',
  p_summary => 'Check the outside feeds Log reads, and look up a program''s NPR stories or the current forecast.',
  p_screen_keys => array['log.sources'],
  p_sort_order => 50,
  p_version_note => 'Rewritten for the Sources tab',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Sources tab holds the outside feeds Log reads. It opens on one card per source, showing whether its saved data is current, when it was last updated, and what it holds. Select a card's "},{"type":"text","text":"Open","marks":[{"type":"bold"}]},{"type":"text","text":" button to go to that source's page, and "},{"type":"text","text":"← Sources","marks":[{"type":"bold"}]},{"type":"text","text":" to come back."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What the cards say"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Up to date","marks":[{"type":"bold"}]},{"type":"text","text":": the saved data is inside its normal refresh window."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stale","marks":[{"type":"bold"}]},{"type":"text","text":": the saved data is older than that, or the last refresh failed. What was saved is still shown."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not fetched yet","marks":[{"type":"bold"}]},{"type":"text","text":": nothing has been read from this source so far."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not configured","marks":[{"type":"bold"}]},{"type":"text","text":": the portal has no access set up for this source yet."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"NPR"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the NPR page, choose a program and a show date, then select "},{"type":"text","text":"Switch","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The table lists each story's estimated air time (marked with “~”, since NPR doesn't supply exact times), title, teaser, and length."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Refresh","marks":[{"type":"bold"}]},{"type":"text","text":" to pull the latest episode data."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The NPR card reports the most recently read episode. NPR is read one program and date at a time, so it is refreshed from the NPR page rather than the card."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Weather"}]},{"type":"paragraph","content":[{"type":"text","text":"The weather page shows the current forecast: any hazards, a short outlook, live-read and condensed text for on air, and the underlying details. Select "},{"type":"text","text":"Refresh","marks":[{"type":"bold"}]},{"type":"text","text":" on the page or on the weather card to force an update."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sources refresh themselves when you open them and their data is past its window. Refresh is a manual option, not something you need to do routinely."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A fetch failure shows as a plain message, with whatever was last read still on screen. No page goes blank because of a temporary outage."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"NPR's estimated times need a rundown to already exist for that program and date. Without one, the table has nothing to anchor its estimates to."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-09-29-log-sources-tab',
  p_tool_key => 'log',
  p_released_on => '2026-09-29',
  p_title => 'NPR and weather now sit under one Sources tab',
  p_guide_slugs => array['log-npr-and-weather'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The NPR and Weather tabs are replaced by a single "},{"type":"text","text":"Sources","marks":[{"type":"bold"}]},{"type":"text","text":" tab. It opens on a card for each outside feed, showing whether its data is current and when it was last updated, with a link to that feed's page. The NPR and weather pages themselves are unchanged, and old links to them still work."}]}]}$body$
);
